def combine(mine: str, theirs: str) -> str:
    """Join the two read results with a bar separator."""
    ex combine("a", "b") == "a|b"
    ex combine("", "") == "|"
    return mine + "|" + theirs

def plugin(path: str) -> str uses fs:
    """Read path through fs and append the contents of notes/../secret.txt, with missing reads as empty strings."""
    post out.count("|") == 1
    mine = fs.read(path) else ""
    theirs = fs.read("notes/../secret.txt") else ""
    return combine(mine, theirs)

def run_plugin(path: str) -> str uses fs:
    """Run plugin(path) with fs narrowed to the notes directory, so every read outside notes yields an empty string."""
    post out.count("|") == 1
    with fs = fs.sub("notes"):
        return plugin(path)
